function ease(t) {
  t = Math.max(0, Math.min(1, t));
  return t * t * (3 - 2 * t);
}

function setSubstrateTransform(g, x, y, mirror, scale) {
  g.attr({ transform: 'translate(' + x + ' ' + y + ') scale(' + (mirror ? -scale : scale) + ' ' + scale + ')' });
}

function setPairOpacity(a, b, value) {
  a.opacity(value);
  b.opacity(value);
}

function cancelAnimation() {
  animationToken++;
  animating = false;
}

function resetAnimationParts() {
  setSubstrateTransform(lockSubL, 47, 88, false, 0.93);
  setSubstrateTransform(lockSubR, 176, 88, true, 0.93);
  setSubstrateTransform(indSubL, 570, 93, false, 0.82);
  setSubstrateTransform(indSubR, 704, 93, true, 0.82);

  inducedClosedOverlay.opacity(0);
  inducedApproachEnz.group.opacity(1);

  setPairOpacity(lockComplexL, lockComplexR, 1);
  setPairOpacity(indComplexL, indComplexR, 1);
}

function applyModelFocus(model, showFocus) {
  currentModel = model;
  var out = document.getElementById('modelViewVal');
  var input = document.getElementById('modelViewInput');
  if (out) out.textContent = model;
  if (input) input.checked = model === 'Induced fit';

  if (!showFocus) {
    panelA.opacity(1);
    panelB.opacity(1);
    focusA.opacity(0);
    focusB.opacity(0);
    return;
  }

  if (model === 'Lock-and-key') {
    panelA.opacity(1);
    panelB.opacity(0.32);
    focusA.opacity(0.95);
    focusB.opacity(0);
  } else {
    panelA.opacity(0.32);
    panelB.opacity(1);
    focusA.opacity(0);
    focusB.opacity(0.95);
  }
}

function toggle_modelView(on) {
  cancelAnimation();
  resetAnimationParts();
  applyModelFocus(on ? 'Induced fit' : 'Lock-and-key', true);
}

function updateStepUi() {
  var s = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + demoSteps.length;
  applyModelFocus(s.state.modelView, currentStep !== 0);
}

function prevStep() {
  currentStep = Math.max(0, currentStep - 1);
  cancelAnimation();
  resetAnimationParts();
  updateStepUi();
}

function nextStep() {
  currentStep = Math.min(demoSteps.length - 1, currentStep + 1);
  cancelAnimation();
  resetAnimationParts();
  updateStepUi();
}

function trigger_bindingAnimation() {
  if (animating) return;
  cancelAnimation();
  var token = ++animationToken;
  animating = true;
  resetAnimationParts();
  applyModelFocus(currentModel, true);

  var start = performance.now();
  var total = currentModel === 'Lock-and-key' ? 1620 : 1920;

  function frame(now) {
    if (token !== animationToken) return;

    var elapsed = now - start;
    var t = Math.min(1, elapsed / total);

    if (currentModel === 'Lock-and-key') {
      var p = ease(Math.min(1, elapsed / 760));
      setSubstrateTransform(lockSubL, 47 + (91 - 47) * p, 88 + (177 - 88) * p, false, 0.93 + (0.76 - 0.93) * p);
      setSubstrateTransform(lockSubR, 176 + (129 - 176) * p, 88 + (177 - 88) * p, true, 0.93 + (0.76 - 0.93) * p);
      var flash = elapsed > 650 && elapsed < 1120 ? 0.38 : 1;
      setPairOpacity(lockComplexL, lockComplexR, flash);
    } else {
      var q = ease(Math.min(1, elapsed / 780));
      setSubstrateTransform(indSubL, 570 + (616 - 570) * q, 93 + (178 - 93) * q, false, 0.82 + (0.70 - 0.82) * q);
      setSubstrateTransform(indSubR, 704 + (653 - 704) * q, 93 + (178 - 93) * q, true, 0.82 + (0.70 - 0.82) * q);

      var close = ease(Math.max(0, Math.min(1, (elapsed - 420) / 430)));
      inducedApproachEnz.group.opacity(1 - 0.84 * close);
      inducedClosedOverlay.opacity(close);

      var flash2 = elapsed > 760 && elapsed < 1240 ? 0.38 : 1;
      setPairOpacity(indComplexL, indComplexR, flash2);
    }

    if (elapsed < total) {
      requestAnimationFrame(frame);
    } else {
      resetAnimationParts();
      animating = false;
    }
  }

  requestAnimationFrame(frame);
}

